// Generates the demo models used for README screenshots.
//
// These are procedural meshes written as 3MF with per-triangle colours
// (basematerials), so they exercise exactly the parts of the app the
// screenshots are meant to show: colour regions, area-weighted analysis,
// colour labels, multi-object layouts.
//
// Everything here is generated by this script — no third-party model data —
// so the models are covered by this repository's MIT license.
//
// Run: node scripts/make-demo-models.mjs   ->  demo/models/*.3mf
import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const OUT = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', 'demo', 'models');

/** HSL (h in degrees, s/l in 0..1) → "#RRGGBB" */
function hsl(h, s, l) {
  const f = (n) => {
    const k = (n + h / 30) % 12;
    const a = s * Math.min(l, 1 - l);
    return Math.round(255 * (l - a * Math.max(-1, Math.min(k - 3, 9 - k, 1))));
  };
  return `#${[f(0), f(8), f(4)].map((v) => v.toString(16).padStart(2, '0')).join('').toUpperCase()}`;
}

/** even hue spread, optionally limited to an arc */
const palette = (n, { from = 0, to = 330, s = 0.72, l = 0.55 } = {}) =>
  Array.from({ length: n }, (_, i) => hsl(from + ((to - from) * i) / Math.max(1, n - 1), s, l));

// ---------------------------------------------------------------- mesh helpers

class Mesh {
  constructor() { this.verts = []; this.tris = []; this.mat = []; }
  v(x, y, z) { this.verts.push([x, y, z]); return this.verts.length - 1; }
  /** triangle from three vertex indices, with a material index */
  face(a, b, c, m) { this.tris.push([a, b, c]); this.mat.push(m); }
  quad(a, b, c, d, m) { this.face(a, b, c, m); this.face(a, c, d, m); }
  bbox() {
    const xs = this.verts.map((p) => p[0]), ys = this.verts.map((p) => p[1]), zs = this.verts.map((p) => p[2]);
    return [Math.max(...xs) - Math.min(...xs), Math.max(...ys) - Math.min(...ys), Math.max(...zs) - Math.min(...zs)].map((n) => +n.toFixed(1));
  }
}

/** surface of revolution: profile(t) -> radius, colour index by height */
function revolve({ segs = 96, steps = 120, height = 90, profile, mats }) {
  const m = new Mesh();
  const rings = [];
  for (let j = 0; j <= steps; j++) {
    const t = j / steps;
    const r = profile(t);
    const y = t * height;
    const ring = [];
    for (let i = 0; i < segs; i++) {
      const a = (2 * Math.PI * i) / segs;
      ring.push(m.v(Math.cos(a) * r, y, Math.sin(a) * r));
    }
    rings.push(ring);
  }
  for (let j = 0; j < steps; j++) {
    for (let i = 0; i < segs; i++) {
      const k = (i + 1) % segs;
      const t = (j + 0.5) / steps;
      const mi = Math.min(mats.length - 1, Math.floor(t * mats.length));
      m.quad(rings[j][i], rings[j][k], rings[j + 1][k], rings[j + 1][i], mi);
    }
  }
  // bottom cap (closed shell: slicers are happier, and the preview looks solid)
  const c = m.v(0, 0, 0);
  for (let i = 0; i < segs; i++) m.face(c, rings[0][(i + 1) % segs], rings[0][i], 0);
  const top = profile(1) > 0.5 ? 1 : 0;
  if (top) {
    const tc = m.v(0, height, 0);
    for (let i = 0; i < segs; i++) m.face(tc, rings[steps][i], rings[steps][(i + 1) % segs], mats.length - 1);
  }
  return m;
}

/** tube swept along a closed curve (used for the knot) */
function tube(curve, { ringSegs = 20, mats }) {
  const m = new Mesh();
  const n = curve.length;
  const rings = [];
  let prevN = [0, 1, 0];
  for (let i = 0; i < n; i++) {
    const p = curve[i], pNext = curve[(i + 1) % n];
    let T = [pNext[0] - p[0], pNext[1] - p[1], pNext[2] - p[2]];
    const tl = Math.hypot(...T) || 1;
    T = T.map((v) => v / tl);
    // parallel-transport-ish frame: project the previous normal onto the plane ⟂ T
    const dot = prevN[0] * T[0] + prevN[1] * T[1] + prevN[2] * T[2];
    let N = prevN.map((v, k) => v - dot * T[k]);
    const nl = Math.hypot(...N) || 1;
    N = N.map((v) => v / nl);
    const B = [T[1] * N[2] - T[2] * N[1], T[2] * N[0] - T[0] * N[2], T[0] * N[1] - T[1] * N[0]];
    prevN = N;
    const r = p[3];
    const ring = [];
    for (let j = 0; j < ringSegs; j++) {
      const a = (2 * Math.PI * j) / ringSegs;
      const ca = Math.cos(a), sa = Math.sin(a);
      ring.push(m.v(p[0] + r * (ca * N[0] + sa * B[0]), p[1] + r * (ca * N[1] + sa * B[1]), p[2] + r * (ca * N[2] + sa * B[2])));
    }
    rings.push(ring);
  }
  for (let i = 0; i < n; i++) {
    const j = (i + 1) % n;
    const mi = Math.min(mats.length - 1, Math.floor((i / n) * mats.length));
    for (let k = 0; k < ringSegs; k++) {
      const l = (k + 1) % ringSegs;
      m.quad(rings[i][k], rings[i][l], rings[j][l], rings[j][k], mi);
    }
  }
  return m;
}

/** stack of twisted bars — reads as a "deck" of colour drawers from the side */
function tower({ levels = 6, w = 26, h = 9, colours }) {
  const m = new Mesh();
  for (let i = 0; i < levels; i++) {
    const y0 = i * (h + 1.5);
    const tw = (i * 12 * Math.PI) / 180;
    const scale = 1 - i * 0.06;
    const hw = (w / 2) * scale;
    const c = Math.cos(tw), s = Math.sin(tw);
    const pts = [[-hw, -hw], [hw, -hw], [hw, hw], [-hw, hw]].map(([x, z]) => [x * c - z * s, x * s + z * c]);
    const lower = pts.map(([x, z]) => m.v(x, y0, z));
    const upper = pts.map(([x, z]) => m.v(x, y0 + h, z));
    for (let k = 0; k < 4; k++) {
      const l = (k + 1) % 4;
      m.quad(lower[k], lower[l], upper[l], upper[k], i);
      m.quad(upper[k], upper[l], lower[l], lower[k], i);
    }
    m.quad(lower[3], lower[2], lower[1], lower[0], i); // bottom
    m.quad(upper[0], upper[1], upper[2], upper[3], i); // top
  }
  return m;
}

// ---------------------------------------------------------------- 3MF writer

function write3mf(mesh, colours, name) {
  const scale = 1;
  const verts = mesh.verts.map((p) => `<vertex x="${(p[0] * scale).toFixed(3)}" y="${(p[1] * scale).toFixed(3)}" z="${(p[2] * scale).toFixed(3)}"/>`).join('');
  const tris = mesh.tris.map((t, i) => `<triangle v1="${t[0]}" v2="${t[1]}" v3="${t[2]}" pid="1" p1="${mesh.mat[i]}"/>`).join('');
  const mats = colours.map((c, i) => `<base name="c${i}" displaycolor="${c}" />`).join('');
  const xml = `<?xml version="1.0" encoding="UTF-8"?>
<model unit="millimeter" xml:lang="en-US" xmlns="http://schemas.microsoft.com/3dmanufacturing/core/2015/02">
 <metadata name="Application">3mfDeck demo models</metadata>
 <metadata name="Title">${name}</metadata>
 <resources>
  <basematerials id="1">${mats}</basematerials>
  <object id="2" type="model" pid="1" pindex="0" name="${name}">
   <mesh><vertices>${verts}</vertices><triangles>${tris}</triangles></mesh>
  </object>
 </resources>
 <build><item objectid="2"/></build>
</model>`;
  return xml;
}

async function save(name, mesh, colours) {
  const dir = path.join(OUT, `${name}.3mf`);
  await fs.mkdir(OUT, { recursive: true });
  // minimal zip writer: one stored (uncompressed) entry is enough for a 3MF
  const { default: JSZip } = await import('jszip');
  const zip = new JSZip();
  zip.file('3D/3dmodel.model', write3mf(mesh, colours, name));
  zip.file('[Content_Types].xml', `<?xml version="1.0" encoding="UTF-8"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
 <Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
 <Default Extension="model" ContentType="application/vnd.ms-package.3dmanufacturing-3dmodel+xml"/>
</Types>`);
  zip.file('_rels/.rels', `<?xml version="1.0" encoding="UTF-8"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
 <Relationship Target="/3D/3dmodel.model" Id="rel0" Type="http://schemas.microsoft.com/3dmanufacturing/2013/01/3dmodel"/>
</Relationships>`);
  const buf = await zip.generateAsync({ type: 'nodebuffer', compression: 'DEFLATE' });
  await fs.writeFile(dir, buf);
  return { file: path.relative(process.cwd(), dir), tris: mesh.tris.length, bbox: mesh.bbox(), size: `${(buf.length / 1024).toFixed(0)} KB` };
}

// ---------------------------------------------------------------- the models

const out = [];
// 1. gradient vase — 12 hue bands, rippled profile: lots of colour area to analyse
out.push(await save('demo-vase', revolve({
  segs: 96, steps: 140, height: 96,
  profile: (t) => 20 + 16 * Math.sin(Math.PI * Math.min(1, t * 1.02)) ** 0.7 + 2.5 * Math.sin(9 * Math.PI * t),
  mats: palette(12, { to: 320 }),
}), palette(12, { to: 320 })));

// 2. torus knot — six colour zones along the curve
{
  const p = 2, q = 3, R = 17, tube0 = 3.2, N = 260;
  const curve = [];
  for (let i = 0; i < N; i++) {
    const t = (2 * Math.PI * i) / N;
    const r = R * (1 + 0.35 * Math.cos(q * t));
    curve.push([r * Math.cos(p * t), 24 + tube0 * 2.2 * Math.sin(q * t) + r * 0.35, r * Math.sin(p * t), tube0]);
  }
  const mats = palette(6, { from: 10, to: 290, l: 0.52 });
  out.push(await save('demo-knot', tube(curve, { ringSegs: 22, mats }), mats));
}

// 3. twisted tower — six discrete colours, one per level
{
  const mats = palette(6, { from: 0, to: 300, l: 0.55 });
  out.push(await save('demo-tower', tower({ levels: 6, colours: mats }), mats));
}

console.log(out.map((o) => `${o.file}  ${o.tris} tris  bbox ${o.bbox.join('×')} mm  ${o.size}`).join('\n'));
